content:
{
    "criteria": [
        {
            "id": "C1",
            "section": "合同主体审查",
            "criterion": "核实签约主体的合法存续性与履约适格性",
            "check_points": [
                "通过国家企业信用信息公示系统或司法大数据平台核查该主体是否存在未结重大涉诉、被执行、失信、破产重整等风险信息",
                "核对营业执照登记的经营范围，确认合同项下标的（如软件采购、技术服务等）属于其法定经营范围内",
                "逐项比对合同载明的主体信息（统一社会信用代码、全称、注册地址、联系地址、联系电话、传真、法定代表人/负责人姓名及职务、指定联系人及联系方式）与最新工商登记信息是否完全一致",
                "如涉及软件、系统、定制开发等采购，核查卖方是否拥有相关核心知识产权（如著作权登记证书、专利证书、授权链文件），或已获得合法有效的再许可权"
            ]
        },
        {
            "id": "C2",
            "section": "合同框架完整性审查",
            "criterion": "确保合同核心条款体系完整、逻辑严密、无结构性缺失",
            "check_points": [
                "检查合同是否完整涵盖以下必备条款：采购内容、合同金额、付款计划、合同期限、生效条件、知识产权归属与使用限制、产品质量/服务标准与保证、交付方式与地点、验收标准与程序、完成时限（含里程碑）、违约责任（含违约金计算方式与上限）、争议解决方式（管辖法院或仲裁机构）、不可抗力定义与处理机制、廉洁合规承诺、合同变更程序、合同份数及效力说明、电子送达效力约定",
                "确认合同中已明确指定主要项目负责人，并完整记载其姓名、身份证号码、联系电话；如为团队服务，应注明对接机制",
                "采购内容须具体列明品种、规格、型号、等级、花色、技术参数、版本号等关键要素；复杂标的须通过附件（如技术规格书、配置清单）予以固化并注明‘为本合同组成部分’",
                "合同金额须同时载明数量、单价、总价、计量单位、币种（如人民币/USD）；大小写金额须完全一致；总价须与各分项合计严格吻合",
                "付款计划须明确分期节点（如预付款、到货款、初验款、终验款、质保金）、对应比例或金额、触发条件（如签收单、验收报告、发票开具）、支付时限（注明‘自然日’或‘工作日’）；质保金比例不低于5%，且明确约定于免费维保期届满后X个工作日内无息支付；注明所需发票类型（增值税专用发票/普通发票）及开票时限"
            ]
        },
        {
            "id": "C3",
            "section": "合同期限与时间表述审查",
            "criterion": "确保期限约定清晰、可执行，杜绝歧义性表述",
            "check_points": [
                "合同期限须以起止日期（YYYY-MM-DD格式）或明确计算方式（如‘自双方签字盖章之日起满12个月’）载明，禁止使用‘长期’‘永久’‘视情况而定’等模糊用语",
                "所有时间单位须明确定义：如‘日’指自然日还是工作日；‘季度’指自然季度（1–3月、4–6月等）还是滚动季度（自起始日起每满3个月）；‘X个月内’须注明自某事件发生之日起算",
                "关键时限（如交付期、验收期、响应时效、维保期）须单独列明，不得隐含于其他条款中"
            ]
        },
        {
            "id": "C4",
            "section": "文本规范性与一致性审查",
            "criterion": "保障合同文本形式严谨、语言准确、内外统一",
            "check_points": [
                "全文通读排查错别字、标点误用、语法错误、数字与单位不匹配（如‘万元’与‘10000元’混用）、标题层级混乱（如一级标题后直接跳至三级标题）",
                "核对合同正文与所有附件（技术协议、服务清单、保密承诺、廉洁协议等）中相同事项的约定是否完全一致，重点比对金额、期限、验收标准、知识产权归属、违约责任等核心条款",
                "清除招标文件、谈判纪要、比选公告等前置流程中残留的非合同用语（如‘投标单位’‘响应人’‘谈判小组’），统一替换为‘甲方’‘乙方’‘双方’等合同主体称谓",
                "合同首部‘甲方/乙方’全称、签约页‘甲方（盖章）’‘乙方（盖章）’处名称、落款签章处名称须完全一致，不得存在简称、缩写、错字或增删字",
                "核查所援引法律法规名称、条款序号是否准确有效（如《民法典》第509条而非已废止的《合同法》第60条），引用司法解释须注明发布文号及现行有效性",
                "合同正文末尾须独立成行、加粗标注‘以下为合同签署栏’或‘以下无正文’字样，防止被擅自添加内容"
            ]
        }
    ]
}
